-- The tests' stand-in for db/vendor/postgresql/V13__create_chunks.sql: the same table, with a real
-- array in place of pgvector's vector(1536) and no HNSW index, since H2 has neither. Change both.
create table chunks (
    id          bigint generated by default as identity primary key,
    source_type varchar(16)              not null,
    alert_id    bigint references alerts (id) on delete cascade,
    report_id   bigint references reports (id) on delete cascade,
    document_id bigint references report_documents (id) on delete cascade,
    user_id     uuid,
    paper_id    uuid references papers (id) on delete cascade,
    chunk_index integer                  not null,
    content     text                     not null,
    page        integer,
    embedding   real array               not null,
    embed_model varchar(64)              not null,
    created_at  timestamp with time zone not null,
    constraint ck_chunks_source check (
        (source_type = 'alert' and alert_id is not null and report_id is null and document_id is null and user_id is null)
        or (source_type = 'report' and report_id is not null and alert_id is null and document_id is null and user_id is null)
        or (source_type = 'document' and document_id is not null and alert_id is null and report_id is null and user_id is null)
        or (source_type = 'profile' and user_id is not null and alert_id is null and report_id is null and document_id is null)),
    constraint ck_chunks_paper check ((source_type = 'profile') = (paper_id is null)),
    constraint ck_chunks_page check (page is null or page >= 1),
    constraint uq_chunks_source_index unique nulls not distinct (source_type, alert_id, report_id, document_id, user_id, chunk_index)
);

create index idx_chunks_paper_type on chunks (paper_id, source_type);
create index idx_chunks_user on chunks (user_id);
